package dev.starfold;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class NativeArrivalStateTest {
    private NativeArrivalState step(NativeArrivalState s,double h,double closing,boolean start,boolean backstop,boolean abort,boolean chart){return s.step(1,"ship",h,closing,start,backstop,abort,chart,true);}
    private NativeArrivalState notice(){return step(NativeArrivalState.empty(),5000,300,true,false,false,false);}
    private NativeArrivalState latched(){var s=notice();for(int i=0;i<80;i++)s=step(s,4000,300,true,false,false,false);return s;}
    @Test void noticeAndBlendTimers(){var s=notice();assertEquals(4,s.seconds());assertFalse(s.latched());for(int i=0;i<60;i++)s=step(s,4500,300,true,false,false,false);assertEquals(1,s.seconds());for(int i=0;i<20;i++)s=step(s,4000,300,true,false,false,false);assertEquals(NativeArrivalState.Phase.TURN_IN,s.phase());assertEquals(0,s.blend());for(int i=0;i<20;i++)s=step(s,3900,150,false,false,false,false);assertEquals(NativeArrivalState.Phase.ARRIVAL,s.phase());assertEquals(1,s.blend());}
    @Test void reducedClosingAndMissCannotFlicker(){var s=latched();for(int i=0;i<200;i++){s=step(s,3900,0,false,false,false,false);assertTrue(s.latched());}}
    @Test void withdrawnNoticeHasCooldown(){var s=step(notice(),5000,0,false,false,false,false);assertEquals(NativeArrivalState.Phase.CRUISE,s.phase());for(int i=0;i<60;i++){s=step(s,5000,300,true,false,false,false);assertEquals(NativeArrivalState.Phase.CRUISE,s.phase());}assertEquals(NativeArrivalState.Phase.NOTICE,step(s,5000,300,true,false,false,false).phase());}
    @Test void backstopDuringNoticeEntersImmediately(){assertTrue(step(notice(),1700,0,false,true,false,false).latched());}
    @Test void abortAtBothLatchedPhasesSuppressesBackstopToo(){var s=latched();for(int i=0;i<2;i++){var a=step(s,1700,300,true,true,true,false);assertFalse(a.latched());for(int j=0;j<60;j++){a=step(a,1700,300,true,true,false,false);assertFalse(a.latched());}s=s.restored();}}
    @Test void leavingRequiresContinuousThreeSecondsOrEntryHeightPlus500(){var s=latched();for(int i=0;i<59;i++)s=step(s,4100,-1,false,false,false,false);assertTrue(s.latched());s=step(s,4100,0,false,false,false,false);assertEquals(0,s.leaving());for(int i=0;i<60;i++)s=step(s,4100,-1,false,false,false,false);assertFalse(s.latched());assertFalse(step(latched(),4501,10,false,false,false,false).latched());}
    @Test void chartAndIdentityReset(){assertEquals(NativeArrivalState.empty(),step(latched(),1500,100,true,true,false,true));assertFalse(latched().step(2,"ship",5000,0,false,false,false,false,true).latched());assertFalse(latched().step(1,"other",5000,0,false,false,false,false,true).latched());}
    @Test void serverSaveRestoresLatchedIdentity()throws Exception{var server=new NativeSpaceServer(NativeSpace.Frame.IDENTITY);var field=NativeSpaceServer.class.getDeclaredField("arrivalState");field.setAccessible(true);for(var state:new NativeArrivalState[]{notice(),latched()}){field.set(server,state);var saved=server.save(new net.minecraft.nbt.CompoundTag(),null);var restored=(NativeArrivalState)field.get(NativeSpaceServer.load(saved,null));assertEquals(state.latched(),restored.latched());if(state.latched()){assertEquals(NativeArrivalState.Phase.ARRIVAL,restored.phase());assertEquals(state.planet(),restored.planet());assertEquals(state.lead(),restored.lead());assertEquals(state.entryHeight(),restored.entryHeight());}}}
    @Test void blendProjectionKeepsCruiseAndRadialEndpoints(){var push=new dev.starfold.BentStripGeometry.Point(3,2,4);var toward=new dev.starfold.BentStripGeometry.Point(0,-1,0);assertEquals(push,NativeSpaceServer.blendPush(push,toward,0));assertEquals(new dev.starfold.BentStripGeometry.Point(1.5,2,2),NativeSpaceServer.blendPush(push,toward,.5));NativeSpaceTest.point(NativeSpaceServer.arrivalPush(push,toward,true),NativeSpaceServer.blendPush(push,toward,1));}
    @Test void restoreAndTurnEasing(){assertEquals(NativeArrivalState.Phase.CRUISE,notice().restored().phase());assertEquals(NativeArrivalState.Phase.ARRIVAL,latched().restored().phase());assertEquals(0,NativeArrivalState.turnScale(0,90));assertEquals(.5,NativeArrivalState.turnScale(.5,90));assertEquals(1,NativeArrivalState.turnScale(1,90));assertEquals(.5,NativeArrivalState.turnScale(1,5));}
}
